postprocess:
float h = saturate((WorldCm.z - FadeStartCm) / max(FadeEndCm - FadeStartCm, 1.0));
// Early visible decay with a long dark tail, anchored exclusively to world height.
float tail = (1.0-h)*(1.0-h)*(1.0+2.0*h);
return exp(-8.0*h*h)*tail;

light_function:
float h = saturate((WorldCm.z - FadeStartCm) / max(FadeEndCm - FadeStartCm, 1.0));
// Broad cubic light transmission avoids duplicating the sharper extinction curve.
return (1.0-h)*(1.0-h)*(1.0+2.0*h);

changes.before:
float h = saturate((WorldCm.z - FadeStartCm) / max(FadeEndCm - FadeStartCm, 1.0));
// Quintic extinction: zero derivatives at both endpoints, fixed world height.
float extinction = h*h*h*(h*(h*6.0-15.0)+10.0);
return 1.0-extinction;

